nodes.text_raw:
* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #0c0a07;
  --fg: #f4ecda;
  --fg-dim: #b8ac96;
  --muted: #6e6557;
  --line: rgba(244, 236, 218, 0.08);
  --line-strong: rgba(244, 236, 218, 0.16);
  --accent: #ff8a3c;
  --accent-rgb: 255, 138, 60;
  --serif: 'Iowan Old Style', 'Palatino Linotype', 'Book Antiqua', Palatino, Georgia, 'Times New Roman', serif;
  --sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
  --mono: ui-monospace, 'SF Mono', 'JetBrains Mono', 'Roboto Mono', Menlo, Consolas, monospace;
}

html, body {
  background: #050402;
  color: var(--fg);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  height: 100%;
  overflow: hidden;
}

body { display: flex; align-items: center; justify-content: center; }

.stage {
  width: 1280px;
  height: 800px;
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(120% 80% at 88% -12%, rgba(var(--accent-rgb), 0.16), transparent 55%),
    radial-gradient(90% 70% at -10% 110%, rgba(var(--accent-rgb), 0.07), transparent 60%),
    linear-gradient(180deg, #0d0a07 0%, #070503 100%);
}

.atmosphere {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.frame {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 100%;
  padding: 40px 56px;
  display: grid;
  grid-template-rows: auto 1fr auto auto;
  gap: 20px;
}

/* Header */
.head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  width: 8px;
  height: 8px;
  background: var(--accent);
  border-radius: 50%;
  box-shadow: 0 0 14px var(--accent);
  animation: pulse 2.4s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.55; transform: scale(0.82); }
}

.brand-text {
  font-family: var(--sans);
  font-size: 10.5px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--fg-dim);
  font-weight: 500;
}

.brand-text .sep { color: var(--muted); margin: 0 10px; }

.head-right {
  display: flex;
  align-items: center;
  gap: 22px;
  font-family: var(--mono);
  font-size: 10.5px;
  color: var(--muted);
  letter-spacing: 0.08em;
}

.head-right .live {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--fg-dim);
}

.live-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
}

/* Body */
.body {
  display: grid;
  grid-template-columns: 1fr 1.32fr;
  gap: 56px;
  min-height: 0;
}

.left {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-width: 0;
}

.location-block { display: flex; flex-direction: column; gap: 4px; }

.eyebrow {
  font-size: 10.5px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 500;
}

.location {
  font-family: var(--serif);
  font-size: 56px;
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.02em;
  color: var(--fg);
  margin-top: 6px;
}

.date-line {
  font-family: var(--mono);
  font-size: 11.5px;
  color: var(--fg-dim);
  letter-spacing: 0.08em;
  margin-top: 8px;
}

.temp-block { margin-top: 14px; }

.temp-main {
  display: flex;
  align-items: flex-start;
  gap: 4px;
  position: relative;
  margin-left: -8px;
}

.temp-value {
  font-family: var(--serif);
  font-size: 196px;
  font-weight: 400;
  line-height: 0.82;
  letter-spacing: -0.06em;
  background: linear-gradient(180deg, var(--fg) 18%, var(--accent) 110%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.temp-unit {
  font-family: var(--serif);
  font-size: 48px;
  line-height: 1;
  color: var(--accent);
  margin-top: 18px;
}

.condition-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 12px;
}

.condition {
  font-family: var(--sans);
  font-size: 13.5px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--fg-dim);
  font-weight: 500;
}

.code-tag {
  font-family: var(--mono);
  font-size: 9.5px;
  color: var(--muted);
  letter-spacing: 0.12em;
  padding: 3px 7px;
  border: 1px solid var(--line-strong);
  border-radius: 2px;
}

.minmax {
  display: flex;
  gap: 36px;
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.minmax-item { display: flex; flex-direction: column; gap: 5px; }

.minmax-label {
  font-size: 9.5px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 500;
}

.minmax-value {
  font-family: var(--serif);
  font-size: 26px;
  color: var(--fg);
  line-height: 1;
}

.minmax-value .small {
  font-size: 13px;
  color: var(--muted);
  margin-left: 2px;
  font-family: var(--sans);
}

/* Right column */
.right {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-height: 0;
  min-width: 0;
}

.right-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.right-meta {
  font-family: var(--mono);
  font-size: 10.5px;
  color: var(--muted);
  letter-spacing: 0.08em;
}

.chart-wrap {
  flex: 1;
  position: relative;
  background: linear-gradient(180deg, rgba(var(--accent-rgb), 0.04), transparent 80%);
  border: 1px solid var(--line);
  border-radius: 2px;
  padding: 16px 12px 8px;
  min-height: 0;
}

.chart-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.chart-svg .g-label {
  font-family: var(--mono);
  font-size: 9px;
  fill: rgba(244, 236, 218, 0.45);
  letter-spacing: 0.04em;
}
.chart-svg .g-grid {
  font-family: var(--mono);
  font-size: 9px;
  fill: rgba(244, 236, 218, 0.38);
  letter-spacing: 0.04em;
}
.chart-svg .g-temp { font-family: var(--serif); font-style: italic; }
.chart-svg .g-temp-max { font-size: 13px; fill: var(--accent); }
.chart-svg .g-temp-min { font-size: 11px; fill: rgba(244, 236, 218, 0.55); }

/* Hourly strip */
.hourly-strip {
  border-top: 1px solid var(--line);
  padding-top: 12px;
}

.hourly-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 8px;
}

.hourly-grid {
  display: grid;
  grid-template-columns: repeat(24, 1fr);
}

.hour-cell {
  text-align: center;
  padding: 5px 0;
  border-right: 1px solid var(--line);
  transition: background 0.18s ease;
  position: relative;
}
.hour-cell:last-child { border-right: none; }
.hour-cell:hover { background: rgba(var(--accent-rgb), 0.10); }
.hour-cell:hover .hour-temp { color: var(--accent); }

.hour-time {
  font-family: var(--mono);
  font-size: 9px;
  color: var(--muted);
  letter-spacing: 0.04em;
}

.hour-temp {
  font-family: var(--serif);
  font-size: 14px;
  color: var(--fg);
  margin-top: 3px;
  line-height: 1;
  transition: color 0.18s ease;
}

/* Footer */
.foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--mono);
  font-size: 9.5px;
  color: var(--muted);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  border-top: 1px solid var(--line);
  padding-top: 14px;
}

.foot .accent { color: var(--accent); }

/* Error state */
.error-state {
  grid-column: 1 / -1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: 100%;
  text-align: center;
  padding: 0 80px;
}

.error-mark {
  width: 10px;
  height: 10px;
  background: var(--accent);
  border-radius: 50%;
  margin-bottom: 28px;
  box-shadow: 0 0 24px var(--accent);
  animation: pulse 1.8s ease-in-out infinite;
}

.error-title {
  font-family: var(--serif);
  font-size: 64px;
  letter-spacing: -0.02em;
  line-height: 1;
  margin: 14px 0 18px;
  color: var(--fg);
}

.error-msg {
  font-size: 14px;
  color: var(--fg-dim);
  max-width: 580px;
  line-height: 1.7;
}

.error-msg strong { color: var(--fg); font-weight: 500; }

.error-detail {
  margin-top: 26px;
  font-family: var(--mono);
  font-size: 10.5px;
  color: var(--muted);
  letter-spacing: 0.08em;
  padding: 12px 18px;
  border: 1px solid var(--line);
  border-radius: 2px;
  max-width: 640px;
  word-break: break-all;
}

/* Loading state */
.loading-state {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  flex-direction: column;
  gap: 16px;
}

.loading-text {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--muted);
  animation: loading-pulse 1.6s ease-in-out infinite;
}

@keyframes loading-pulse {
  0%, 100% { opacity: 0.35; }
  50% { opacity: 1; }
}

/* Reveal */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.reveal { animation: fadeUp 0.6s cubic-bezier(0.2, 0.7, 0.2, 1) forwards; opacity: 0; }
.reveal-1 { animation-delay: 0.05s; }
.reveal-2 { animation-delay: 0.15s; }
.reveal-3 { animation-delay: 0.25s; }
.reveal-4 { animation-delay: 0.35s; }
.reveal-5 { animation-delay: 0.45s; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

const params = new URLSearchParams(location.search);
const lat = parseFloat(params.get('lat') ?? '52.52');
const lon = parseFloat(params.get('lon') ?? '13.405');
const nameParam = params.get('name') ?? 'Berlin';
const dateParam = params.get('date');
const todayUTC = new Date().toISOString().slice(0, 10);
const date = dateParam && /^\d{4}-\d{2}-\d{2}$/.test(dateParam) ? dateParam : todayUTC;

const isPast = date < todayUTC;
const endpoint = isPast ? '/api/om/archive' : '/api/om/forecast';

const qs = new URLSearchParams({
  latitude: lat.toString(),
  longitude: lon.toString(),
  daily: 'temperature_2m_max,temperature_2m_min,weather_code',
  hourly: 'temperature_2m',
  timezone: 'UTC',
  temperature_unit: 'celsius',
  start_date: date,
  end_date: date
});

const apiUrl = `${endpoint}?${qs.toString()}`;

const WMO = {
  0:  { label: 'Clear sky',                  family: 'clear' },
