function accentForTemp(t) {
  if (t == null || Number.isNaN(t)) return '#ff8a3c';
  if (t <= -10) return '#7dd3fc';
  if (t <= 0)   return '#a5e8e0';
  if (t <= 8)   return '#cfe8b8';
  if (t <= 18)  return '#ffd07a';
  if (t <= 26)  return '#ff8a3c';
  return '#ff5a3c';
}

function hexToRgb(hex) {
  hex = hex.replace('#', '');
  return [
    parseInt(hex.slice(0, 2), 16),
    parseInt(hex.slice(2, 4), 16),
    parseInt(hex.slice(4, 6), 16)
  ].join(', ');
}

function formatDateLong(d) {
  const dt = new Date(d + 'T00:00:00Z');
  const opts = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' };
  return dt.toLocaleDateString('en-US', opts);
}

function formatCoord(lat, lon) {
  const latDir = lat >= 0 ? 'N' : 'S';
  const lonDir = lon >= 0 ? 'E' : 'W';
  return `${Math.abs(lat).toFixed(3)}°${latDir} · ${Math.abs(lon).toFixed(3)}°${lonDir}`;
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#039;');
}

function smoothPath(points) {
  if (points.length < 2) return '';
  const p = points;
  let d = `M ${p[0][0].toFixed(2)} ${p[0][1].toFixed(2)}`;
  const t = 0.18;
  for (let i = 0; i < p.length - 1; i++) {
    const p0 = p[i - 1] || p[i];
    const p1 = p[i];
    const p2 = p[i + 1];
    const p3 = p[i + 2] || p2;
    const cp1x = p1[0] + (p2[0] - p0[0]) * t;
    const cp1y = p1[1] + (p2[1] - p0[1]) * t;
    const cp2x = p2[0] - (p3[0] - p1[0]) * t;
    const cp2y = p2[1] - (p3[1] - p1[1]) * t;
    d += ` C ${cp1x.toFixed(2)} ${cp1y.toFixed(2)}, ${cp2x.toFixed(2)} ${cp2y.toFixed(2)}, ${p2[0].toFixed(2)} ${p2[1].toFixed(2)}`;
  }
  return d;
}

function buildChart(hours, temps, accent, W, H) {
  W = Math.max(200, W);
  H = Math.max(150, H);
  const padL = 38, padR = 16, padT = 26, padB = 26;
  const innerW = W - padL - padR;
  const innerH = H - padT - padB;

  const tMin = Math.min(...temps);
  const tMax = Math.max(...temps);
  const range = Math.max(0.5, tMax - tMin);
  const pad = range * 0.22;
  const yMin = tMin - pad;
  const yMax = tMax + pad;
  const yRange = Math.max(0.5, yMax - yMin);

  const xStep = innerW / Math.max(1, hours.length - 1);

  const points = temps.map((t, i) => {
    const x = padL + i * xStep;
    const y = padT + (1 - (t - yMin) / yRange) * innerH;
    return [x, y];
  });

  const path = smoothPath(points);
  const lastPt = points[points.length - 1];
  const firstPt = points[0];
  const areaPath = path +
    ` L ${lastPt[0].toFixed(2)} ${(H - padB).toFixed(2)}` +
    ` L ${firstPt[0].toFixed(2)} ${(H - padB).toFixed(2)} Z`;

  let gridLines = '';
  const gridCount = 4;
  for (let i = 0; i <= gridCount; i++) {
    const y = padT + (i / gridCount) * innerH;
    const val = yMax - (i / gridCount) * yRange;
    gridLines += `<line x1="${padL}" y1="${y.toFixed(2)}" x2="${(W - padR).toFixed(2)}" y2="${y.toFixed(2)}" stroke="rgba(244,236,218,0.05)" stroke-width="1"/>`;
    gridLines += `<text x="${(padL - 8).toFixed(2)}" y="${(y + 3).toFixed(2)}" text-anchor="end" class="g-grid">${val.toFixed(0)}°</text>`;
  }

  let xLabels = '';
  hours.forEach((h, i) => {
    if (i % 3 !== 0 && i !== hours.length - 1) return;
    const hh = h.split('T')[1].slice(0, 2);
    const x = padL + i * xStep;
    xLabels += `<text x="${x.toFixed(2)}" y="${(H - 9).toFixed(2)}" text-anchor="middle" class="g-label">${hh}h</text>`;
  });

  let dots = '';
  points.forEach(([x, y], i) => {
    if (i % 3 !== 0 && i !== points.length - 1) return;
    dots += `<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="2.2" fill="${accent}" opacity="0.95"/>`;
  });

  const maxIdx = temps.indexOf(tMax);
  const minIdx = temps.indexOf(tMin);
  const peak = `
    <line x1="${points[maxIdx][0].toFixed(2)}" y1="${points[maxIdx][1].toFixed(2)}" x2="${points[maxIdx][0].toFixed(2)}" y2="${(H - padB).toFixed(2)}" stroke="${accent}" stroke-width="1" stroke-dasharray="2 3" opacity="0.4"/>
    <line x1="${points[minIdx][0].toFixed(2)}" y1="${points[minIdx][1].toFixed(2)}" x2="${points[minIdx][0].toFixed(2)}" y2="${(H - padB).toFixed(2)}" stroke="rgba(244,236,218,0.3)" stroke-width="1" stroke-dasharray="2 3" opacity="0.4"/>
    <circle cx="${points[maxIdx][0].toFixed(2)}" cy="${points[maxIdx][1].toFixed(2)}" r="4.5" fill="none" stroke="${accent}" stroke-width="1.2" opacity="0.95"/>
    <text x="${points[maxIdx][0].toFixed(2)}" y="${(points[maxIdx][1] - 11).toFixed(2)}" text-anchor="middle" class="g-temp g-temp-max">${tMax.toFixed(1)}°</text>
    <circle cx="${points[minIdx][0].toFixed(2)}" cy="${points[minIdx][1].toFixed(2)}" r="3.5" fill="none" stroke="rgba(244,236,218,0.5)" stroke-width="1"/>
    <text x="${points[minIdx][0].toFixed(2)}" y="${(points[minIdx][1] + 17).toFixed(2)}" text-anchor="middle" class="g-temp g-temp-min">${tMin.toFixed(1)}°</text>
  `;

  return `
    <svg class="chart-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">
      <defs>
        <linearGradient id="area-grad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="${accent}" stop-opacity="0.34"/>
          <stop offset="100%" stop-color="${accent}" stop-opacity="0"/>
        </linearGradient>
        <linearGradient id="line-grad" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stop-color="${accent}" stop-opacity="0.55"/>
          <stop offset="50%" stop-color="${accent}" stop-opacity="1"/>
          <stop offset="100%" stop-color="${accent}" stop-opacity="0.55"/>
        </linearGradient>
      </defs>
      ${gridLines}
      <path d="${areaPath}" fill="url(#area-grad)"/>
      <path d="${path}" fill="none" stroke="url(#line-grad)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>
      ${peak}
      ${dots}
      ${xLabels}
    </svg>
  `;
}

function render(d) {
