            <span class="temp-unit">°C</span>
          </div>
          <div class="condition-row">
            <span class="condition">${d.wmo.label}</span>
            <span class="code-tag">WMO ${d.code}</span>
          </div>
          <div class="minmax">
            <div class="minmax-item">
              <span class="minmax-label">High</span>
              <span class="minmax-value">${d.tMax.toFixed(1)}<span class="small">°C</span></span>
            </div>
            <div class="minmax-item">
              <span class="minmax-label">Low</span>
              <span class="minmax-value">${d.tMin.toFixed(1)}<span class="small">°C</span></span>
            </div>
            <div class="minmax-item">
              <span class="minmax-label">Range</span>
              <span class="minmax-value">${range}<span class="small">°C</span></span>
            </div>
          </div>
        </div>
      </section>

      <section class="right reveal reveal-3">
        <div class="right-head">
          <span class="eyebrow">Hourly Temperature · 24h Trace</span>
          <span class="right-meta">${d.hours.length} readings · °C</span>
        </div>
        <div class="chart-wrap" id="chartWrap"></div>
      </section>
    </main>

    <section class="hourly-strip reveal reveal-4">
      <div class="hourly-head">
        <span class="eyebrow">Hourly Breakdown</span>
        <span class="right-meta">00h → 23h UTC</span>
      </div>
      <div class="hourly-grid">${cells}</div>
    </section>

    <footer class="foot reveal reveal-5">
      <span>Source · Open-Meteo · <span class="accent">${d.isPast ? 'Archive API' : 'Forecast API'}</span></span>
      <span>Generated ${generated} UTC</span>
    </footer>
  `;

  // Build chart after layout settles, so we can size to container
  requestAnimationFrame(() => {
    const wrap = document.getElementById('chartWrap');
    if (wrap) {
      const rect = wrap.getBoundingClientRect();
      const cw = Math.max(200, Math.round(rect.width - 24));
      const ch = Math.max(150, Math.round(rect.height - 24));
      wrap.innerHTML = buildChart(d.hours, d.temps, accent, cw, ch);
    }
    startAtmosphere(d.wmo.family, accent);
  });
}

function renderError(e) {
  document.documentElement.style.setProperty('--accent', '#ff8a3c');
  document.documentElement.style.setProperty('--accent-rgb', '255, 138, 60');
  const frame = document.getElementById('frame');
  frame.innerHTML = `
    <div class="error-state">
      <div class="error-mark"></div>
      <div class="eyebrow">Signal Lost · Report Unavailable</div>
      <h1 class="error-title">The atmosphere is silent.</h1>
      <p class="error-msg">
        Weather data for <strong>${escapeHtml(nameParam)}</strong> on <strong>${escapeHtml(date)}</strong> could not be retrieved.
        The observation service may be unreachable, the requested date may fall outside the available range,
        or the coordinates may be invalid.
      </p>
      <div class="error-detail">${escapeHtml(e.message || 'Unknown error')} &nbsp;·&nbsp; ${escapeHtml(apiUrl)}</div>
    </div>`;
  startAtmosphere('clear', '#ff8a3c');
}

async function init() {
  try {
    const res = await fetch(apiUrl);
    if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
    const data = await res.json();

    const daily = data.daily;
    const hourly = data.hourly;

    if (!daily || !hourly) throw new Error('Incomplete response: missing daily or hourly data');
    if (!Array.isArray(daily.temperature_2m_max) || daily.temperature_2m_max.length === 0)
      throw new Error('No daily data returned for the requested date');
    if (!Array.isArray(hourly.temperature_2m) || hourly.temperature_2m.length === 0)
      throw new Error('No hourly data returned for the requested date');

    const tMax = daily.temperature_2m_max[0];
    const tMin = daily.temperature_2m_min[0];
    const code = daily.weather_code[0];

    if (tMax == null || tMin == null)
      throw new Error('Temperature values are null for the requested date');

    const hours = hourly.time;
    const temps = hourly.temperature_2m;
    const wmo = WMO[code] ?? { label: 'Unknown conditions', family: 'clear' };

    render({ name: nameParam, date, lat, lon, tMax, tMin, code, wmo, hours, temps, isPast });
  } catch (e) {
    console.error(e);
    renderError(e);
  }
}

function startAtmosphere(family, accent) {
  const canvas = document.getElementById('atmosphere');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const W = 1280, H = 800;
  canvas.width = W * dpr;
  canvas.height = H * dpr;
  canvas.style.width = W + 'px';
  canvas.style.height = H + 'px';
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const accentRgb = hexToRgb(accent);
  let particles = [];
  const rand = (min, max) => min + Math.random() * (max - min);

  if (family === 'rain' || family === 'drizzle') {
    const count = family === 'drizzle' ? 90 : 180;
    particles = Array.from({ length: count }, () => ({
      x: rand(0, W), y: rand(-H, H),
      vy: rand(5, 9), vx: rand(0.6, 1.2),
      len: rand(10, 20), a: rand(0.15, 0.4)
    }));
  } else if (family === 'snow') {
    particles = Array.from({ length: 80 }, () => ({
      x: rand(0, W), y: rand(-H, H),
      vy: rand(0.4, 1.1), vx: rand(-0.4, 0.4),
      r: rand(1, 2.6), a: rand(0.4, 0.85),
      drift: rand(0, Math.PI * 2), driftSpeed: rand(0.01, 0.03)
    }));
  } else if (family === 'fog') {
    particles = Array.from({ length: 8 }, () => ({
      x: rand(-200, W), y: rand(H * 0.2, H * 0.95),
      r: rand(180, 320), vx: rand(0.15, 0.4),
      a: rand(0.04, 0.09)
    }));
  } else if (family === 'storm') {
    particles = Array.from({ length: 220 }, () => ({
      x: rand(0, W), y: rand(-H, H),
      vy: rand(6, 11), vx: rand(0.8, 1.6),
      len: rand(12, 22), a: rand(0.2, 0.5)
    }));
  } else if (family === 'cloudy' || family === 'partly') {
    particles = Array.from({ length: 5 }, () => ({
      x: rand(-200, W), y: rand(40, 320),
      r: rand(140, 260), vx: rand(0.12, 0.28),
      a: rand(0.04, 0.08)
    }));
  } else {
    particles = Array.from({ length: 70 }, () => ({
      x: rand(0, W), y: rand(0, H),
      r: rand(0.4, 1.4), a: rand(0.08, 0.32),
      twinkle: rand(0, Math.PI * 2), twinkleSpeed: rand(0.008, 0.025)
    }));
  }

  let flashOpacity = 0;
  let nextFlashAt = performance.now() + rand(2000, 5000);

  function frame(t) {
    ctx.clearRect(0, 0, W, H);

    if (family === 'rain' || family === 'drizzle' || family === 'storm') {
      ctx.strokeStyle = `rgba(${accentRgb}, 0.9)`;
      ctx.lineWidth = 1;
      ctx.lineCap = 'round';
      for (const p of particles) {
        ctx.globalAlpha = p.a;
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - p.vx * 1.5, p.y + p.len);
        ctx.stroke();
        p.x += p.vx;
        p.y += p.vy;
        if (p.y > H + 10) { p.y = -10; p.x = rand(0, W); }
        if (p.x > W + 10) p.x = -10;
      }
      if (family === 'storm') {
        if (t > nextFlashAt) {
          flashOpacity = 0.32;
          nextFlashAt = t + rand(2800, 6500);
        }
        if (flashOpacity > 0.005) {
          ctx.globalAlpha = flashOpacity;
          ctx.fillStyle = '#f4ecda';
          ctx.fillRect(0, 0, W, H);
          flashOpacity *= 0.82;
        }
      }
    } else if (family === 'snow') {
      ctx.fillStyle = '#f4ecda';
      for (const p of particles) {
        p.drift += p.driftSpeed;
        p.x += p.vx + Math.sin(p.drift) * 0.4;
        p.y += p.vy;
        if (p.y > H + 5) { p.y = -5; p.x = rand(0, W); }
        if (p.x > W + 5) p.x = -5;
        if (p.x < -5) p.x = W + 5;
        ctx.globalAlpha = p.a;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (family === 'fog' || family === 'cloudy' || family === 'partly') {
      for (const p of particles) {
        p.x += p.vx;
        if (p.x > W + p.r) p.x = -p.r;
        const grad = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r);
        grad.addColorStop(0, `rgba(244, 236, 218, ${p.a})`);
        grad.addColorStop(1, 'rgba(244, 236, 218, 0)');
        ctx.globalAlpha = 1;
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
      }
    } else {
      ctx.fillStyle = '#f4ecda';
      for (const p of particles) {
        p.twinkle += p.twinkleSpeed;
        const a = p.a * (0.35 + 0.65 * (0.5 + 0.5 * Math.sin(p.twinkle)));
        ctx.globalAlpha = a;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    ctx.globalAlpha = 1;
    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
}

init();
